import React, { useState } from "react";
import "./Hero.css";

function Hero() {
  // State to track selected image
  const [selected, setSelected] = useState(null);

  // Monastery image data
  const monasteries = [
    {
      id: 1,
      src: "/assets/hero1.png",
      title: "Rumtek Monastery",
      desc: "Rumtek Monastery, also called Dharmachakra Centre, is one of the most important seats of the Kagyu lineage in Sikkim."
    },
    {
      id: 2,
      src: "/assets/hero2.png",
      title: "Pemayangtse Monastery",
      desc: "Pemayangtse, built in 1705, is a premier monastery of the Nyingma order, rich in murals and sculptures."
    },
    {
      id: 3,
      src: "/assets/hero3.png",
      title: "Tashiding Monastery",
      desc: "Tashiding is regarded as the spiritual heart of Sikkim, located on a hilltop with breathtaking views."
    },
    {
      id: 4,
      src: "/assets/hero4.png",
      title: "Enchey Monastery",
      desc: "Built during the reign of Sidkeong Tulku, Enchey Monastery is dedicated to the tantric master Lama Drupthob Karpo."
    },
    {
      id: 5,
      src: "/assets/hero5.png",
      title: "Phodong Monastery",
      desc: "Phodong Monastery is one of the six most important monasteries of Sikkim, rebuilt in the 18th century."
    },
    {
      id: 6,
      src: "/assets/hero6.png",
      title: "Ralang Monastery",
      desc: "Ralang Monastery is known for its traditional Tibetan architecture and vibrant mask dance festivals."
    },
  ];

  return (
    <section className="hero">
      <h1 className="hero-title">Explore the Monasteries of Sikkim</h1>
      <p className="hero-subtitle">Click on a monastery to learn more about its history and culture.</p>

      <div className="hero-gallery">
        {monasteries.map((m) => (
          <div
            key={m.id}
            className={`hero-card ${selected && selected.id === m.id ? "active" : ""}`}
            onClick={() => setSelected(m)}
          >
            <img src={m.src} alt={m.title} className="hero-image" />
            <div className="hero-overlay">
              <h3>{m.title}</h3>
              <p>{m.desc}</p>
            </div>
          </div>
        ))}
      </div>

      {selected && (
        <div className="hero-details">
          <button className="close-btn" onClick={() => setSelected(null)}>✖ Close</button>
          <h2>{selected.title}</h2>
          <img src={selected.src} alt={selected.title} />
          <p>{selected.desc}</p>
        </div>
      )}
    </section>
  );
}

export default Hero;
